import{_ as e}from"./chunks/popup-function.kMGNX6Sw.js";import{_ as d,o as a,c as r,a2 as o}from"./chunks/framework.CfwCq2QB.js";const m=JSON.parse('{"title":"DevGo 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),l={name:"guide/index.md"};function s(i,t,h,n,c,f){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="devgo-是什么" tabindex="-1">DevGo 是什么 <a class="header-anchor" href="#devgo-是什么" aria-label="Permalink to &quot;DevGo 是什么&quot;">​</a></h1><p>DevGo 是一个面向开发者的浏览器效率扩展：把翻译、AI 助手、代理与隐私防护、资源嗅探这些高频需求放进一个扩展里，支持 Chrome 与 Firefox，界面中英双语。</p><p>与其装五六个各管一件事的扩展，DevGo 想做到的是：每个功能单独拿出来都能打，合在一起又共享同一套配置和交互。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>一句话介绍</th><th>详见</th></tr></thead><tbody><tr><td>整页双语翻译</td><td>译文插在原文后面，边读边对照；支持 Shadow DOM 页面</td><td><a href="/dev-go-docs/features/page-translate.html">整页双语翻译</a></td></tr><tr><td>划词工具条</td><td>选中文字即翻译 / 解释 / 总结，AI 动作可以自己定义</td><td><a href="/dev-go-docs/features/selection-toolbar.html">划词工具条</a></td></tr><tr><td>AI 助手</td><td>侧边栏一键总结本页、就网页内容提问</td><td><a href="/dev-go-docs/features/assistant.html">AI 助手</a></td></tr><tr><td>网页工具（WebMCP）</td><td>AI 直接调用网页注册的工具，替你在页面上操作</td><td><a href="/dev-go-docs/features/webmcp.html">网页工具（WebMCP）</a></td></tr><tr><td>代理与自动分流</td><td>四种网络模式一键切换，规则自动分流</td><td><a href="/dev-go-docs/features/proxy.html">代理与自动分流</a></td></tr><tr><td>真实 IP 防护</td><td>开着代理时，防止网站借 WebRTC 拿到你的真实 IP</td><td><a href="/dev-go-docs/features/ip-protection.html">真实 IP 防护</a></td></tr><tr><td>资源嗅探</td><td>嗅探当前页面的图片 / 视频 / 音频，批量下载</td><td><a href="/dev-go-docs/features/media-sniffer.html">资源嗅探</a></td></tr><tr><td>悬浮快捷栏</td><td>网页右侧的快捷按钮：翻译、AI 总结、回到顶部</td><td><a href="/dev-go-docs/features/dock.html">悬浮快捷栏</a></td></tr><tr><td>新标签页</td><td>搜索引擎 + bang 语法、快捷导航、动态背景</td><td><a href="/dev-go-docs/features/newtab.html">新标签页</a></td></tr><tr><td>网页增强</td><td>按站点解除复制限制、GitHub 增强</td><td><a href="/dev-go-docs/features/page-enhance.html">网页增强</a></td></tr></tbody></table><h2 id="界面速览" tabindex="-1">界面速览 <a class="header-anchor" href="#界面速览" aria-label="Permalink to &quot;界面速览&quot;">​</a></h2><p>DevGo 的日常操作集中在三个地方：</p><ul><li><strong>弹窗</strong>：点工具栏图标（或按 <code>Alt+1</code>），四个页签——翻译、网络、资源、功能，只放与当前页面相关的高频操作。</li><li><strong>侧边栏</strong>：按 <code>Alt+2</code> 打开 AI 助手，总结网页、就内容提问。</li><li><strong>设置页</strong>：所有配置都在这里，按 翻译 / AI 模型 / 划词 / AI 助手 / 网络 / 网页增强 / 通用 分区。</li></ul><img src="'+e+'" alt="功能总览：弹窗「功能」页"><blockquote><p><a href="/dev-go-docs/guide/install.html">安装</a> 之后，跟着 <a href="/dev-go-docs/guide/quick-start.html">快速上手（5 分钟）</a> 走一遍即可。</p></blockquote><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="https://chrome.google.com/webstore/detail/devgo/kcofdbjhicjdbmldlcffcijglkifnnjn" target="_blank" rel="noreferrer">Chrome 应用商店</a></li><li><a href="https://github.com/fedtop/DevGo" target="_blank" rel="noreferrer">GitHub 仓库</a></li><li><a href="https://github.com/fedtop/DevGo/releases" target="_blank" rel="noreferrer">GitHub Releases 离线安装包</a></li></ul>',12)])])}const b=d(l,[["render",s]]);export{m as __pageData,b as default};
